/// <reference types="cypress" />

/*
 * ./big is generated by "npm run generate" and is plain JavaScript whose only purpose is to make
 * this bundle large. "modules" is read below so that no part of the graph can be dropped as unused.
 */
import { megabytes, modules } from '../../big/index.js'

describe('page', () => {
  it('works', () => {
    /*
     * cy.task reaches the runner's stdout while the test runs, unlike cy.log. The line before the
     * visit is therefore the last thing printed when the run stalls.
     */
    cy.task('log', `bundle: ${megabytes} MB in ${modules.length} modules`)
    cy.task('log', 'visiting ...')
    cy.visit('https://example.cypress.io')
    cy.task('log', 'visit returned')
  })
})
